class Solution {
public:
    long long countDistinct(long long n) {
        unordered_set<long long> s;
        for (long long x = 1; x <= n; x++) {
            long long v = 0;
            for (long long t = x; t > 0; t /= 10)
                if (t % 10) v = v * 10 + t % 10;
            s.insert(v);
        }
        return s.size();
    }
};

