class Solution {
    public long countDistinct(long n) {
        Set<Long> s = new HashSet<>();
        for (long x = 1; x <= n; x++) {
            long v = 0;
            for (long t = x; t > 0; t /= 10)
                if (t % 10 != 0) v = v * 10 + t % 10;
            s.add(v);
        }
        return s.size();
    }
}

