class Solution:
    def countDistinct(self, n):
        s = str(n)
        L = len(s)
        ans = sum(9 ** k for k in range(1, L))
        for i, ch in enumerate(s):
            d = int(ch)
            ans += (d - 1) * 9 ** (L - 1 - i)
            if d == 0:
                return ans
        return ans + 1

