class Solution {
public:
    long long countDistinct(long long n) {
        string s = to_string(n);
        int L = s.size();
        long long ans = 0;
        for (int k = 1; k < L; k++) {
            long long p = 1;
            for (int t = 0; t < k; t++) p *= 9;
            ans += p;
        }
        for (int i = 0; i < L; i++) {
            int d = s[i] - '0';
            long long p = 1;
            for (int t = 0; t < L - 1 - i; t++) p *= 9;
            ans += (long long)(d - 1) * p;
            if (d == 0) return ans;
        }
        return ans + 1;
    }
};

